import{_ as i,c as l,o as e,a0 as s}from"./chunks/framework.oTSD2LDJ.js";const c=JSON.parse('{"title":"常见问题","description":"","frontmatter":{"title":"常见问题","layout":"doc","editLink":true},"headers":[],"relativePath":"faq.md","filePath":"zh/faq.md"}'),t={name:"faq.md"};function n(o,a,r,h,d,p){return e(),l("div",null,a[0]||(a[0]=[s(`<h1 id="常见问题-faq" tabindex="-1">常见问题 FAQ <a class="header-anchor" href="#常见问题-faq" aria-label="Permalink to &quot;常见问题 FAQ&quot;">​</a></h1><p>这里汇总了用户在使用 Uniquenium 过程中最常遇到的问题。如果你没有找到答案，欢迎在 GitHub 提交 Issue。</p><h2 id="安装与启动" tabindex="-1">安装与启动 <a class="header-anchor" href="#安装与启动" aria-label="Permalink to &quot;安装与启动&quot;">​</a></h2><h3 id="q-编译时提示「找不到-qt6」或-cmake-报错" tabindex="-1">Q: 编译时提示「找不到 Qt6」或 CMake 报错 <a class="header-anchor" href="#q-编译时提示「找不到-qt6」或-cmake-报错" aria-label="Permalink to &quot;Q: 编译时提示「找不到 Qt6」或 CMake 报错&quot;">​</a></h3><p><strong>A:</strong> 请确保：</p><ol><li>已正确安装 Qt 6.5.0+，并在安装时勾选了所需模块（Core, Widgets, Quick, QuickControls2, DBus, Core5Compat, LabsPlatform, Concurrent）</li><li>配置 CMake 时正确指定了 Qt 路径：<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DCMAKE_PREFIX_PATH=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:/Qt/6.8.3/msvc2022_64&quot;</span></span></code></pre></div></li><li>已安装 ECM（Extra CMake Modules）</li></ol><h3 id="q-程序一闪而过-没有任何窗口显示" tabindex="-1">Q: 程序一闪而过，没有任何窗口显示 <a class="header-anchor" href="#q-程序一闪而过-没有任何窗口显示" aria-label="Permalink to &quot;Q: 程序一闪而过，没有任何窗口显示&quot;">​</a></h3><p><strong>A:</strong> 请尝试以下步骤：</p><ol><li>检查托盘区（右下角任务栏）是否有 Uniquenium 图标，程序默认最小化到托盘</li><li>如果没有托盘图标，使用命令行启动查看错误信息：<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Release</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Uniquenium0.exe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --debug</span></span></code></pre></div></li><li>确保显卡驱动已更新到最新版本</li><li>尝试在软件渲染模式下运行（性能较低）：<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> QMLSCENE_DEVICE=softwarecontext</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Release</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Uniquenium0.exe</span></span></code></pre></div></li></ol><h3 id="q-安装程序被-windows-defender-smartscreen-拦截" tabindex="-1">Q: 安装程序被 Windows Defender / SmartScreen 拦截 <a class="header-anchor" href="#q-安装程序被-windows-defender-smartscreen-拦截" aria-label="Permalink to &quot;Q: 安装程序被 Windows Defender / SmartScreen 拦截&quot;">​</a></h3><p><strong>A:</strong> 这是正常现象，因为程序没有购买代码签名证书。请：</p><ol><li>点击「更多信息」→「仍要运行」</li><li>或右键安装程序 → 属性 → 勾选「解除锁定」→ 确定</li></ol><h3 id="q-旧版-windows-10-壁纸功能异常" tabindex="-1">Q: 旧版 Windows 10 壁纸功能异常 <a class="header-anchor" href="#q-旧版-windows-10-壁纸功能异常" aria-label="Permalink to &quot;Q: 旧版 Windows 10 壁纸功能异常&quot;">​</a></h3><p><strong>A:</strong> 部分旧版本 Windows 10（1809 之前）的壁纸 API 存在兼容性问题，建议升级到 Windows 10 21H2 或 Windows 11。</p><h2 id="使用操作" tabindex="-1">使用操作 <a class="header-anchor" href="#使用操作" aria-label="Permalink to &quot;使用操作&quot;">​</a></h2><h3 id="q-如何添加组件到桌面" tabindex="-1">Q: 如何添加组件到桌面？ <a class="header-anchor" href="#q-如何添加组件到桌面" aria-label="Permalink to &quot;Q: 如何添加组件到桌面？&quot;">​</a></h3><p><strong>A:</strong> 操作步骤：</p><ol><li>打开主面板（默认快捷键：<code>Ctrl + Alt + U</code>）</li><li>点击左侧「+ 新建页面」或选择已有页面</li><li>点击「添加组件」按钮</li><li>从组件列表中选择需要的组件类型</li><li>拖拽调整组件位置和大小</li></ol><h3 id="q-如何删除组件" tabindex="-1">Q: 如何删除组件？ <a class="header-anchor" href="#q-如何删除组件" aria-label="Permalink to &quot;Q: 如何删除组件？&quot;">​</a></h3><p><strong>A:</strong> 有三种方式：</p><ol><li>选中组件后按 <code>Delete</code> 键</li><li>右键组件 → 选择「删除」</li><li>在页面管理窗口的组件树中右键 → 「删除」</li></ol><h3 id="q-组件不小心拖到屏幕外找不到了怎么办" tabindex="-1">Q: 组件不小心拖到屏幕外找不到了怎么办？ <a class="header-anchor" href="#q-组件不小心拖到屏幕外找不到了怎么办" aria-label="Permalink to &quot;Q: 组件不小心拖到屏幕外找不到了怎么办？&quot;">​</a></h3><p><strong>A:</strong> 打开页面管理窗口（设置 → 页面管理），在组件树中选中该组件，右侧属性面板中重置 X/Y 坐标为 0。</p><h3 id="q-如何调整组件的层级-z-轴顺序" tabindex="-1">Q: 如何调整组件的层级（Z 轴顺序）？ <a class="header-anchor" href="#q-如何调整组件的层级-z-轴顺序" aria-label="Permalink to &quot;Q: 如何调整组件的层级（Z 轴顺序）？&quot;">​</a></h3><p><strong>A:</strong></p><ol><li>选中组件</li><li>右键 → 选择「上移一层」/「下移一层」/「置于顶层」/「置于底层」</li><li>或在组件树中直接拖拽调整顺序</li></ol><h2 id="主题与外观" tabindex="-1">主题与外观 <a class="header-anchor" href="#主题与外观" aria-label="Permalink to &quot;主题与外观&quot;">​</a></h2><h3 id="q-如何切换深色-浅色主题" tabindex="-1">Q: 如何切换深色/浅色主题？ <a class="header-anchor" href="#q-如何切换深色-浅色主题" aria-label="Permalink to &quot;Q: 如何切换深色/浅色主题？&quot;">​</a></h3><p><strong>A:</strong></p><ol><li>右键托盘图标 → 设置 → 外观</li><li>选择主题模式：跟随系统 / 浅色 / 深色</li><li>也可以使用快捷键快速切换（需先在设置中绑定）</li></ol><h3 id="q-亚克力模糊效果不显示" tabindex="-1">Q: 亚克力模糊效果不显示 <a class="header-anchor" href="#q-亚克力模糊效果不显示" aria-label="Permalink to &quot;Q: 亚克力模糊效果不显示&quot;">​</a></h3><p><strong>A:</strong> 亚克力效果依赖：</p><ul><li>Windows 10 1803+ 或 Windows 11</li><li>显卡支持硬件加速</li><li>在设置 → 外观中确认已开启「启用亚克力效果」</li></ul><p>如果仍然不显示，尝试更新显卡驱动。</p><h3 id="q-可以使用自定义壁纸吗" tabindex="-1">Q: 可以使用自定义壁纸吗？ <a class="header-anchor" href="#q-可以使用自定义壁纸吗" aria-label="Permalink to &quot;Q: 可以使用自定义壁纸吗？&quot;">​</a></h3><p><strong>A:</strong> 可以！支持：</p><ul><li>本地图片（JPG/PNG/BMP/WebP）</li><li>多张图片轮播</li><li>自定义 API 接口获取网络壁纸 设置路径：设置 → 外观 → 壁纸</li></ul><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><h3 id="q-全局快捷键不生效" tabindex="-1">Q: 全局快捷键不生效 <a class="header-anchor" href="#q-全局快捷键不生效" aria-label="Permalink to &quot;Q: 全局快捷键不生效&quot;">​</a></h3><p><strong>A:</strong> 请检查：</p><ol><li>快捷键是否与其他软件冲突（如 QQ、微信、输入法等）</li><li>是否以管理员权限运行（部分系统热键需要管理员权限）</li><li>设置 → 快捷键中确认热键已启用</li><li>尝试重新绑定一个不常用的组合键</li></ol><h3 id="q-如何修改-删除快捷键" tabindex="-1">Q: 如何修改/删除快捷键？ <a class="header-anchor" href="#q-如何修改-删除快捷键" aria-label="Permalink to &quot;Q: 如何修改/删除快捷键？&quot;">​</a></h3><p><strong>A:</strong></p><ol><li>打开设置 → 快捷键</li><li>找到要修改的功能</li><li>点击快捷键输入框，按下新的组合键</li><li>点击「应用」保存</li><li>如需删除，点击输入框旁的「清除」按钮</li></ol><h2 id="插件与模板" tabindex="-1">插件与模板 <a class="header-anchor" href="#插件与模板" aria-label="Permalink to &quot;插件与模板&quot;">​</a></h2><h3 id="q-如何安装第三方插件" tabindex="-1">Q: 如何安装第三方插件？ <a class="header-anchor" href="#q-如何安装第三方插件" aria-label="Permalink to &quot;Q: 如何安装第三方插件？&quot;">​</a></h3><p><strong>A:</strong></p><ol><li>下载插件包（通常为 <code>.zip</code> 或 <code>.uniq-plugin</code>）</li><li>打开设置 → 插件</li><li>点击「安装插件」按钮，选择下载的文件</li><li>或手动将插件解压到：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%APPDATA%\\Uniquenium\\Plugins\\</span></span></code></pre></div></li><li>重启程序</li></ol><h3 id="q-插件安装后不显示-不工作" tabindex="-1">Q: 插件安装后不显示/不工作 <a class="header-anchor" href="#q-插件安装后不显示-不工作" aria-label="Permalink to &quot;Q: 插件安装后不显示/不工作&quot;">​</a></h3><p><strong>A:</strong> 请：</p><ol><li>检查插件版本是否与 Uniquenium 版本匹配</li><li>查看设置 → 插件中是否已启用该插件</li><li>打开日志窗口（设置 → 关于 → 查看日志）查看错误信息</li><li>联系插件作者或在 GitHub 提交 Issue</li></ol><h3 id="q-如何导出-导入页面模板" tabindex="-1">Q: 如何导出/导入页面模板？ <a class="header-anchor" href="#q-如何导出-导入页面模板" aria-label="Permalink to &quot;Q: 如何导出/导入页面模板？&quot;">​</a></h3><p><strong>A:</strong></p><ol><li><strong>导出</strong>：在页面上右键 → 导出为模板 → 选择保存位置</li><li><strong>导入</strong>：新建页面时选择「从模板导入」→ 选择模板文件</li><li>模板文件包含页面布局和所有组件配置，不包含外部图片资源</li></ol><h2 id="性能相关" tabindex="-1">性能相关 <a class="header-anchor" href="#性能相关" aria-label="Permalink to &quot;性能相关&quot;">​</a></h2><h3 id="q-程序占用内存过高" tabindex="-1">Q: 程序占用内存过高 <a class="header-anchor" href="#q-程序占用内存过高" aria-label="Permalink to &quot;Q: 程序占用内存过高&quot;">​</a></h3><p><strong>A:</strong> 建议优化：</p><ol><li>减少同时显示的组件数量</li><li>关闭不必要的插件</li><li>降低壁纸模糊半径（设置 → 外观 → 模糊强度）</li><li>避免使用过大分辨率的壁纸图片</li></ol><h3 id="q-拖动窗口时有卡顿" tabindex="-1">Q: 拖动窗口时有卡顿 <a class="header-anchor" href="#q-拖动窗口时有卡顿" aria-label="Permalink to &quot;Q: 拖动窗口时有卡顿&quot;">​</a></h3><p><strong>A:</strong> 这是 Qt 无边框窗口的已知问题，可尝试：</p><ol><li>更新显卡驱动到最新版</li><li>关闭不必要的后台程序释放 GPU 资源</li><li>在设置中关闭「窗口阴影」和「亚克力效果」</li></ol><h2 id="开发相关" tabindex="-1">开发相关 <a class="header-anchor" href="#开发相关" aria-label="Permalink to &quot;开发相关&quot;">​</a></h2><h3 id="q-如何获取程序日志" tabindex="-1">Q: 如何获取程序日志？ <a class="header-anchor" href="#q-如何获取程序日志" aria-label="Permalink to &quot;Q: 如何获取程序日志？&quot;">​</a></h3><p><strong>A:</strong> 有三种方式：</p><ol><li>命令行启动时加 <code>--debug</code> 参数，日志直接输出到控制台</li><li>设置 → 关于 → 点击「查看日志」按钮</li><li>直接打开日志文件：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%APPDATA%\\Uniquenium\\Logs\\uniquenium-YYYY-MM-DD.log</span></span></code></pre></div></li></ol><h3 id="q-如何参与开发或提交代码" tabindex="-1">Q: 如何参与开发或提交代码？ <a class="header-anchor" href="#q-如何参与开发或提交代码" aria-label="Permalink to &quot;Q: 如何参与开发或提交代码？&quot;">​</a></h3><p><strong>A:</strong> 欢迎贡献！请：</p><ol><li>Fork 项目仓库到你的 GitHub 账号</li><li>创建新分支开发功能或修复 Bug</li><li>确保代码通过现有测试</li><li>提交 Pull Request，详细说明修改内容</li></ol><h3 id="q-想要的功能没有怎么办" tabindex="-1">Q: 想要的功能没有怎么办？ <a class="header-anchor" href="#q-想要的功能没有怎么办" aria-label="Permalink to &quot;Q: 想要的功能没有怎么办？&quot;">​</a></h3><p><strong>A:</strong> 可以：</p><ol><li>先查看 <a href="https://github.com/Uniquenium/Uniquenium/blob/main/TODO.md" target="_blank" rel="noreferrer">TODO 列表</a> 是否已经在计划中</li><li>自己开发插件实现（参考<a href="/custom-developing/plugin">插件开发指南</a>）</li><li>在 GitHub 提交 Feature Request Issue，详细描述需求和使用场景</li></ol><h2 id="数据与备份" tabindex="-1">数据与备份 <a class="header-anchor" href="#数据与备份" aria-label="Permalink to &quot;数据与备份&quot;">​</a></h2><h3 id="q-配置文件和数据保存在哪里" tabindex="-1">Q: 配置文件和数据保存在哪里？ <a class="header-anchor" href="#q-配置文件和数据保存在哪里" aria-label="Permalink to &quot;Q: 配置文件和数据保存在哪里？&quot;">​</a></h3><p><strong>A:</strong> 用户数据默认保存在：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Windows: %APPDATA%\\Uniquenium\\</span></span>
<span class="line"><span>├── Pages\\         # 页面配置文件</span></span>
<span class="line"><span>├── Plugins\\       # 已安装的插件</span></span>
<span class="line"><span>├── Settings\\      # 程序设置</span></span>
<span class="line"><span>├── Templates\\     # 导出的模板</span></span>
<span class="line"><span>└── Logs\\          # 日志文件</span></span></code></pre></div><h3 id="q-如何备份和迁移数据" tabindex="-1">Q: 如何备份和迁移数据？ <a class="header-anchor" href="#q-如何备份和迁移数据" aria-label="Permalink to &quot;Q: 如何备份和迁移数据？&quot;">​</a></h3><p><strong>A:</strong> 只需将整个 <code>%APPDATA%\\Uniquenium\\</code> 文件夹复制到新电脑的相同位置即可。建议定期备份该文件夹。</p><hr><p>没有找到你的问题？</p><ul><li><a href="/">📖 查看官方文档</a></li><li><a href="https://github.com/Uniquenium/Uniquenium/issues" target="_blank" rel="noreferrer">🐛 提交 GitHub Issue</a></li><li><a href="https://github.com/Uniquenium/Uniquenium/discussions" target="_blank" rel="noreferrer">💬 参与讨论</a></li></ul>`,80)]))}const q=i(t,[["render",n]]);export{c as __pageData,q as default};
